    "item.detector.n": ["ДЕТЕКТОР", "DETECTOR", "ДЕТЕКТОР", "ДЕТЕКТОР"],
    "item.detector.d": ["10 с показывает дистанцию до монстра.", "Shows the distance to the monster for 10 s.", "10 с бойы құбыжыққа дейінгі қашықтықты көрсетеді.", "10 с показує відстань до монстра."],
    "item.mirror.n": ["ЗЕРКАЛО", "MIRROR", "АЙНА", "ДЗЕРКАЛО"],
    "item.mirror.d": ["Стрелка к ключу/детали. −25% рассудка.", "An arrow to a key/part. −25% sanity.", "Кілтке/бөлшекке бағыттайтын нұсқар. −25% ақыл.", "Стрілка до ключа/деталі. −25% розсудку."],
