    "junk.0": ["Пусто.", "Empty.", "Бос.", "Порожньо."],
    "junk.1": ["Только пыль.", "Just dust.", "Тек шаң.", "Лише пил."],
    "junk.2": ["Старая фотография. Лица стёрты.", "An old photograph. The faces are scratched out.", "Ескі фотосурет. Беттері өшіп кеткен.", "Стара фотографія. Обличчя стерті."],
    "junk.3": ["Сломанная лампочка.", "A broken light bulb.", "Сынған шам.", "Розбита лампочка."],
    "junk.4": ["Записка: «Не оглядывайся»", "A note: “Don't look back”", "Жазба: «Артыңа қарама»", "Записка: «Не озирайся»"],
    "junk.5": ["Пусто. Но кто-то был здесь недавно.", "Empty. But someone was here recently.", "Бос. Бірақ жақында біреу осында болған.", "Порожньо. Але хтось був тут нещодавно."],
    "junk.6": ["Записка: «Лифт не едет. Я слышал, как он зовёт».", "A note: “The elevator isn't moving. I heard it calling.”", "Жазба: «Лифт жүрмейді. Оның шақырғанын естідім».", "Записка: «Ліфт не їде. Я чув, як він кличе»."],
    "junk.7": ["Детский рисунок. Все фигурки без лиц.", "A child's drawing. All the figures have no faces.", "Балалар суреті. Барлық фигуралардың беті жоқ.", "Дитячий малюнок. Усі постаті без облич."],
    "junk.8": ["Ржавый ключ от несуществующей двери.", "A rusty key to a door that doesn't exist.", "Жоқ есіктің тот басқан кілті.", "Іржавий ключ від неіснуючих дверей."],
    "junk.9": ["Записка: «Они любят свет. Я больше не включаю фонарь».", "A note: “They love the light. I don't turn on my flashlight anymore.”", "Жазба: «Олар жарықты жақсы көреді. Мен енді қол шамды қоспаймын».", "Записка: «Вони люблять світло. Я більше не вмикаю ліхтар»."],
